namespace grove { int leaf(); }
namespace other { int leaf(); }
int grove::leaf() { return 1; }
int wrong_namespace() { return other::leaf(); }

namespace grove {
class Box { public: int member(); };
struct packet { int read(); };
}
int grove::Box::member() { return 2; }
int grove::packet::read() { return 3; }

namespace left::shared { int duplicate(); class Box { public: int twin(); }; }
namespace right::shared { int duplicate(); class Box { public: int twin(); }; }
int left::shared::duplicate() { return 4; }
int right::shared::duplicate() { return 5; }
int left::shared::Box::twin() { return 6; }
int right::shared::Box::twin() { return 7; }
